52	
53		private static final int HIGHER_PRECEDENCE = -1;
54	
55		private static final int SAME_PRECEDENCE = 0;
56	
57		private static final int LOWER_PRECEDENCE = 1;
58	
59	
60		private final Comparator<? super Advisor> advisorComparator;
61	
