64		 * Create a default {@code AspectJPrecedenceComparator}.
65		 */
66		public AspectJPrecedenceComparator() {
67			this.advisorComparator = AnnotationAwareOrderComparator.INSTANCE;
68		}
69	
70		/**
71		 * Create an {@code AspectJPrecedenceComparator}, using the given {@link Comparator}
72		 * for comparing {@link org.springframework.aop.Advisor} instances.
73		 * @param advisorComparator the {@code Comparator} to use for advisors
74		 */
75		public AspectJPrecedenceComparator(Comparator<? super Advisor> advisorComparator) {
76			Assert.notNull(advisorComparator, "Advisor comparator must not be null");
77			this.advisorComparator = advisorComparator;
78		}
