81		@Override
82		public int compare(Advisor o1, Advisor o2) {
83			int advisorPrecedence = this.advisorComparator.compare(o1, o2);
84			if (advisorPrecedence == SAME_PRECEDENCE && declaredInSameAspect(o1, o2)) {
85				advisorPrecedence = comparePrecedenceWithinAspect(o1, o2);
