90		private int comparePrecedenceWithinAspect(Advisor advisor1, Advisor advisor2) {
91			boolean oneOrOtherIsAfterAdvice =
92					(AspectJAopUtils.isAfterAdvice(advisor1) || AspectJAopUtils.isAfterAdvice(advisor2));
93			int adviceDeclarationOrderDelta = getAspectDeclarationOrder(advisor1) - getAspectDeclarationOrder(advisor2);
94	
95			if (oneOrOtherIsAfterAdvice) {
96				// the advice declared last has higher precedence
97				if (adviceDeclarationOrderDelta < 0) {
98					// advice1 was declared before advice2
99					// so advice1 has lower precedence
100					return LOWER_PRECEDENCE;
101				}
102				else if (adviceDeclarationOrderDelta == 0) {
103					return SAME_PRECEDENCE;
104				}
105				else {
106					return HIGHER_PRECEDENCE;
107				}
108			}
109			else {
110				// the advice declared first has higher precedence
111				if (adviceDeclarationOrderDelta < 0) {
112					// advice1 was declared before advice2
113					// so advice1 has higher precedence
114					return HIGHER_PRECEDENCE;
115				}
116				else if (adviceDeclarationOrderDelta == 0) {
117					return SAME_PRECEDENCE;
118				}
119				else {
120					return LOWER_PRECEDENCE;
121				}
122			}
123		}
